//create an API service as native Object
BalanceReadService service = GatewayProxyFactory.getInstance().create(BalanceReadService.class, config);
//init your API call parameter
BaseOpenApiReq req = new BaseOpenApiReq();
//invoke api as native call and get the deserialized result Object
RichOpenRes<List<BalanceDetailRes>> res = service.list(req);
//if invoke succeed do your business
if (res.isSuccess()) {
    //do your business here
    System.out.println(res);
    System.out.println(JSONObject.toJSON(res));
    if (res.getModel() != null) {
        System.out.println("return balance list:");
        res.getModel().forEach(e -> {
            System.out.println("accountId:" + e.getAccountId() + "\t\t" + "accountId:" + e.getAccountId() + "\t\t" + "availableAmount:" + e.getAvailableAmount());
        });
    }
} else {//if invoked error check the return error message and do your error handler
    //error handler
    System.out.println("there is a error for API invoke, the detail message is:");
    System.out.println("error:" + res.getError());
    System.out.println("message:" + res.getMessage());
    System.out.println("success:" + res.isSuccess());
    System.out.println("code:" + res.getCode());
}
